const workflows={"helios":{"title":"HELIOS workflow","summary":"Hindi/Hinglish voice intake with symptom-specific follow-ups and specialization routing.","url":"https://github.com/nik07-droid/HELIOS","steps":[["Give consent and enable the microphone","Open the patient experience, review the consent notice, and allow microphone access."],["Describe the concern","Speak in Hindi or Hinglish. HELIOS responds in Hindi with spoken audio and on-screen captions."],["Capture structured facts","Gemini Live submits reported details; the Java backend validates them and preserves uncertainty or negation."],["Answer tailored follow-ups","Backend rules choose the next question using missing details, contradictions, and symptom-specific information."],["Save intake and route","PostgreSQL stores the completed record and recommended starting specialization for a later clinical workflow."]],"note":"The hospital scene has five animated guides. HELIOS is a prototype; native voice needs configured Gemini access, and this application does not include a doctor dashboard."},"captain":{"title":"Captain workflow","summary":"A browser agent loop from command to checked result.","url":"https://github.com/nik07-droid/captain-browser-agent","steps":[["Enter a typed or voice command","Use the page panel or activate the voice controller."],["Clarify missing details","If the request is incomplete, ask a follow-up question before continuing."],["Observe the browser","Collect current DOM context and local visual perception in the Incognito working tab."],["Sanitize the context","Redact sensitive content locally; visual privacy checks fail closed."],["Choose the next action","Use bounded command handling or the configured local / remote planner."],["Validate & execute","Validate the action, then navigate, search, click, type, or scroll in the browser."],["Observe & verify the result","Check the new page state and supported task-specific success criteria."],["Continue or report","More work: return to observation. Verified task: report the result. Model-only completion: review required."]],"note":"Cancel stops subsequent actions. This is a prototype; unsupported tasks and model-only results are not guaranteed."}};
const dialog=document.getElementById('workflow-dialog');let trigger;document.querySelectorAll('[data-workflow]').forEach(button=>button.addEventListener('click',()=>{trigger=button;const flow=workflows[button.dataset.workflow];document.getElementById('workflow-title').textContent=flow.title;document.getElementById('workflow-summary').textContent=flow.summary;document.getElementById('workflow-note').textContent=flow.note;document.getElementById('workflow-source').href=flow.url;const chart=document.getElementById('workflow-chart');chart.replaceChildren();flow.steps.forEach(([title,description],index)=>{const node=document.createElement('li');const number=document.createElement('span');number.className='flow-number';number.textContent=String(index+1).padStart(2,'0');const heading=document.createElement('h3');heading.textContent=title;const detail=document.createElement('p');detail.textContent=description;node.append(number,heading,detail);chart.append(node);});dialog.dataset.project=button.dataset.workflow;dialog.showModal();dialog.scrollTop=0;}));document.getElementById('workflow-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>trigger?.focus());